/* ============================================
   GreenBean Coffee — Design System
   Palette: OKLCH perceptual color space
   Typography: DM Serif Display + Inter
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Primary Brand */
  --green-primary: oklch(52% 0.17 152);
  --green-primary-hover: oklch(45% 0.18 152);
  --green-primary-light: oklch(92% 0.04 152);
  --green-primary-muted: oklch(75% 0.1 152);
  --dark-forest: oklch(30% 0.03 148);
  --warm-cream: oklch(87% 0.07 75);
  --warm-cream-light: oklch(94% 0.04 75);

  /* Neutrals */
  --white: oklch(100% 0 0);
  --off-white: oklch(97% 0.005 100);
  --gray-50: oklch(95% 0.005 100);
  --gray-100: oklch(92% 0.005 100);
  --gray-200: oklch(85% 0.008 100);
  --gray-300: oklch(75% 0.01 100);
  --gray-400: oklch(60% 0.01 100);
  --gray-500: oklch(50% 0.01 100);
  --gray-600: oklch(40% 0.01 100);
  --gray-700: oklch(30% 0.01 100);
  --gray-800: oklch(25% 0.01 100);
  --near-black: oklch(20% 0.02 148);

  /* Accent */
  --coffee-brown: oklch(38% 0.08 55);
  --coffee-brown-light: oklch(55% 0.09 55);
  --gold-accent: oklch(80% 0.14 80);
  --mango-accent: oklch(78% 0.15 75);
  --lavender-accent: oklch(72% 0.1 300);

  /* Semantic */
  --color-success: oklch(60% 0.18 145);
  --color-error: oklch(55% 0.2 25);
  --color-warning: oklch(75% 0.15 80);

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  --leading-tight: 1.15;
  --leading-snug: 1.3;
  --leading-normal: 1.6;
  --leading-relaxed: 1.75;

  --tracking-tight: -0.02em;
  --tracking-normal: 0;
  --tracking-wide: 0.02em;

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --max-width: 1440px;
  --content-width: 1200px;
  --sidebar-width: 280px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.08), 0 2px 4px -2px oklch(0% 0 0 / 0.04);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.04);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.04);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.45, 0, 0.55, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;
}

/* --- Reset & Base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--near-black);
  background-color: var(--white);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

@media (max-width: 768px) {
  h1 { font-size: var(--text-4xl); }
  h2 { font-size: var(--text-3xl); }
  h3 { font-size: var(--text-2xl); }
  h4 { font-size: var(--text-xl); }
}

p {
  line-height: var(--leading-normal);
  max-width: 65ch;
}

/* --- Layout Containers --- */
.container {
  width: 100%;
  max-width: var(--content-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.container--wide {
  max-width: var(--max-width);
}

.container--narrow {
  max-width: 800px;
}

.section {
  padding-block: var(--space-16);
}

.section--sm {
  padding-block: var(--space-10);
}

.section--lg {
  padding-block: var(--space-24);
}

/* --- Header / Navigation --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-base) var(--ease-out);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.nav-primary {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-primary a {
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--near-black);
  position: relative;
  padding-block: var(--space-2);
  transition: color var(--duration-fast);
}

.nav-primary a:hover,
.nav-primary a.active {
  color: var(--green-primary);
}

.nav-primary a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--duration-base) var(--ease-out);
}

.nav-primary a:hover::after,
.nav-primary a.active::after {
  width: 100%;
}

.nav-account {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-account a {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--near-black);
  transition: color var(--duration-fast);
}

.nav-account a:hover {
  color: var(--green-primary);
}

.find-store-link {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--near-black) !important;
  transition: color var(--duration-fast);
}

.find-store-link:hover {
  color: var(--green-primary) !important;
}

.find-store-link::after {
  display: none !important;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--near-black);
  border-radius: 2px;
  transition: all var(--duration-base) var(--ease-out);
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

@media (max-width: 1024px) {
  .nav-toggle {
    display: flex;
  }

  .nav-primary,
  .nav-account {
    display: none;
  }

  .nav-primary.open,
  .nav-account.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--white);
    padding: var(--space-6);
    border-bottom: 1px solid var(--gray-200);
    box-shadow: var(--shadow-lg);
  }

  .nav-primary.open {
    z-index: 10;
  }

  .nav-account.open {
    top: auto;
    z-index: 9;
  }
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-full);
  transition: all var(--duration-base) var(--ease-out);
  cursor: pointer;
  white-space: nowrap;
}

.btn--primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--green-primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn--outline {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn--outline:hover {
  background: var(--green-primary);
  color: var(--white);
}

.btn--dark {
  background: var(--dark-forest);
  color: var(--white);
}

.btn--dark:hover {
  background: var(--near-black);
  transform: translateY(-1px);
}

.btn--cream {
  background: var(--warm-cream);
  color: var(--dark-forest);
}

.btn--cream:hover {
  background: var(--warm-cream-light);
  transform: translateY(-1px);
}

.btn--white {
  background: var(--white);
  color: var(--green-primary);
}

.btn--white:hover {
  background: var(--gray-50);
  transform: translateY(-1px);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
}

.btn--icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
}

/* --- Cards --- */
.card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-base) var(--ease-out);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: var(--gray-100);
}

.card__body {
  padding: var(--space-6);
}

.card__tag {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--green-primary);
  margin-bottom: var(--space-2);
}

.card__title {
  font-size: var(--text-xl);
  margin-bottom: var(--space-2);
}

.card__text {
  font-size: var(--text-sm);
  color: var(--gray-500);
  margin-bottom: var(--space-4);
}

/* --- Promo Sections --- */
.promo-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 480px;
}

.promo-section--reverse {
  direction: rtl;
}

.promo-section--reverse > * {
  direction: ltr;
}

.promo__content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: var(--space-12);
}

.promo__image {
  position: relative;
  overflow: hidden;
}

.promo__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-6xl);
}

.promo__subtitle {
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  margin-bottom: var(--space-3);
}

.promo__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
  max-width: 20ch;
}

.promo__text {
  font-size: var(--text-lg);
  color: var(--gray-500);
  margin-bottom: var(--space-6);
  max-width: 45ch;
}

@media (max-width: 768px) {
  .promo-section {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .promo__content {
    padding: var(--space-8);
  }

  .promo__image {
    min-height: 280px;
    order: -1;
  }

  .promo__title {
    font-size: var(--text-3xl);
  }
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  color: var(--gray-400);
}

.breadcrumb a {
  color: var(--gray-500);
  transition: color var(--duration-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb__sep {
  color: var(--gray-300);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  border-bottom: 2px solid var(--gray-200);
  padding-bottom: 0;
  margin-bottom: var(--space-8);
}

.tab-btn {
  padding: var(--space-3) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--gray-500);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--duration-base);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.tab-btn:hover {
  color: var(--green-primary);
}

.tab-btn.active {
  color: var(--green-primary);
  border-bottom-color: var(--green-primary);
}

.tab-content {
  display: none;
  animation: fadeIn var(--duration-base) var(--ease-out);
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-4);
  transition: transform var(--duration-slow) var(--ease-out);
  will-change: transform;
}

.carousel__slide {
  flex: 0 0 auto;
}

.carousel__nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-lg);
  color: var(--near-black);
  transition: all var(--duration-base);
}

.carousel__btn:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.carousel__btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel__btn:disabled:hover {
  background: var(--white);
  border-color: var(--gray-200);
  color: var(--near-black);
}

/* --- Gift Card --- */
.gift-card {
  width: 180px;
  height: 112px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  text-align: center;
  color: var(--white);
  padding: var(--space-2);
  cursor: pointer;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.gift-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.gift-card--spring { background: linear-gradient(135deg, oklch(55% 0.15 152), oklch(70% 0.12 130)); }
.gift-card--perk { background: linear-gradient(135deg, oklch(65% 0.18 75), oklch(80% 0.12 60)); }
.gift-card--friend { background: linear-gradient(135deg, oklch(55% 0.12 200), oklch(70% 0.1 220)); }
.gift-card--thank { background: linear-gradient(135deg, oklch(50% 0.1 30), oklch(65% 0.08 45)); }
.gift-card--star { background: linear-gradient(135deg, oklch(75% 0.16 80), oklch(85% 0.1 75)); color: var(--dark-forest); }
.gift-card--work { background: linear-gradient(135deg, oklch(35% 0.08 55), oklch(50% 0.06 60)); }
.gift-card--birthday { background: linear-gradient(135deg, oklch(65% 0.2 340), oklch(75% 0.15 350)); }
.gift-card--celebrate { background: linear-gradient(135deg, oklch(60% 0.2 280), oklch(70% 0.15 300)); }
.gift-card--yay { background: linear-gradient(135deg, oklch(70% 0.18 55), oklch(80% 0.12 70)); color: var(--dark-forest); }
.gift-card--encourage { background: linear-gradient(135deg, oklch(52% 0.17 152), oklch(68% 0.12 155)); }
.gift-card--greenbean { background: linear-gradient(135deg, var(--dark-forest), var(--green-primary)); }
.gift-card--cafe { background: linear-gradient(135deg, oklch(40% 0.08 55), oklch(55% 0.06 60)); }
.gift-card--heritage { background: linear-gradient(135deg, oklch(30% 0.06 148), oklch(45% 0.08 55)); }

/* --- Toggle / Switch --- */
.toggle-group {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: var(--space-1);
}

.toggle-btn {
  padding: var(--space-2) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--gray-500);
  transition: all var(--duration-base);
}

.toggle-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Accordion --- */
.accordion {
  border-top: 1px solid var(--gray-200);
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--near-black);
  cursor: pointer;
}

.accordion__icon {
  transition: transform var(--duration-base) var(--ease-out);
  font-size: var(--text-lg);
}

.accordion__trigger.open .accordion__icon {
  transform: rotate(180deg);
}

.accordion__panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out);
}

.accordion__panel.open {
  max-height: 500px;
}

.accordion__panel a {
  display: block;
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--gray-500);
  transition: color var(--duration-fast);
}

.accordion__panel a:hover {
  color: var(--green-primary);
}

/* --- Footer --- */
.site-footer {
  background: var(--dark-forest);
  color: var(--gray-300);
  padding-block: var(--space-16);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--white);
  margin-bottom: var(--space-4);
}

.footer-col a {
  display: block;
  font-size: var(--text-sm);
  color: var(--gray-300);
  padding-block: var(--space-1);
  transition: color var(--duration-fast);
}

.footer-col a:hover {
  color: var(--warm-cream);
}

.footer-bottom {
  margin-top: var(--space-12);
  padding-top: var(--space-6);
  border-top: 1px solid oklch(40% 0.02 148);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--text-xs);
  color: var(--gray-400);
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  border: 1px solid oklch(50% 0.02 148);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  transition: all var(--duration-base);
}

.footer-social a:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-col h4 {
    display: none;
  }

  .footer-col .footer-links-list {
    display: none;
  }

  .footer-col.accordion-mobile .accordion__trigger {
    display: flex;
  }

  .footer-col.accordion-mobile .footer-links-list {
    display: none;
  }

  .footer-col.accordion-mobile .accordion__panel.open .footer-links-list {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }
}

/* Desktop: hide accordion triggers */
@media (min-width: 769px) {
  .footer-col .accordion__trigger {
    display: none;
  }

  .footer-col .accordion__panel {
    max-height: none !important;
    overflow: visible;
  }

  .footer-col .accordion__panel .footer-links-list {
    display: block !important;
  }
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--dark-forest);
  color: var(--gray-200);
  padding: var(--space-6);
  box-shadow: 0 -4px 20px oklch(0% 0 0 / 0.15);
  transform: translateY(0);
  transition: transform var(--duration-slow) var(--ease-out);
}

.cookie-banner.hidden {
  transform: translateY(110%);
}

.cookie-banner__inner {
  max-width: var(--content-width);
  margin-inline: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.cookie-banner__text h3 {
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--white);
  margin-bottom: var(--space-1);
}

.cookie-banner__text p {
  font-size: var(--text-sm);
  max-width: 55ch;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .cookie-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

/* --- Utility --- */
.text-center { text-align: center; }
.text-green { color: var(--green-primary); }
.text-cream { color: var(--warm-cream); }
.text-dark { color: var(--dark-forest); }
.bg-green-light { background: var(--green-primary-light); }
.bg-cream { background: var(--warm-cream-light); }
.bg-off-white { background: var(--off-white); }
.bg-forest { background: var(--dark-forest); }
.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }

/* --- Image Placeholder --- */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  background: var(--gray-100);
  color: var(--gray-300);
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--gray-100);
}

::-webkit-scrollbar-thumb {
  background: var(--gray-300);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--gray-400);
}

/* ============================================
   GreenBean Coffee — Design System
   Palette: OKLCH perceptual color space
   Typography: DM Serif Display + Inter
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Primary Brand */
  --green-primary: oklch(52% 0.17 152);
  --green-primary-hover: oklch(45% 0.18 152);
  --green-primary-light: oklch(92% 0.04 152);
  --green-primary-muted: oklch(75% 0.1 152);
  --dark-forest: oklch(30% 0.03 148);
  --warm-cream: oklch(87% 0.07 75);
  --warm-cream-light: oklch(94% 0.04 75);

  /* Neutrals */
  --white: oklch(100% 0 0);
  --off-white: oklch(97% 0.005 100);
  --gray-50: oklch(95% 0.005 100);
  --gray-100: oklch(92% 0.005 100);
  --gray-200: oklch(85% 0.008 100);
  --gray-300: oklch(75% 0.01 100);
  --gray-400: oklch(60% 0.01 100);
  --gray-500: oklch(50% 0.01 100);
  --gray-600: oklch(40% 0.01 100);
  --gray-700: oklch(30% 0.01 100);
  --gray-800: oklch(25% 0.01 100);
  --near-black: oklch(20% 0.02 148);

  /* Accent */
  --coffee-brown: oklch(38% 0.08 55);
  --coffee-brown-light: oklch(55% 0.09 55);
  --gold-accent: oklch(80% 0.14 80);
  --mango-accent: oklch(78% 0.15 75);
  --lavender-accent: oklch(72% 0.1 300);

  /* Semantic */
  --color-success: oklch(60% 0.18 145);
  --color-error: oklch(55% 0.2 25);
  --color-warning: oklch(75% 0.15 80);

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  --leading-tight: 1.15;
  --leading-snug: 1.3;
  --leading-normal: 1.6;
  --leading-relaxed: 1.75;

  --tracking-tight: -0.02em;
  --tracking-normal: 0;
  --tracking-wide: 0.02em;

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --max-width: 1440px;
  --content-width: 1200px;
  --sidebar-width: 280px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.08), 0 2px 4px -2px oklch(0% 0 0 / 0.04);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.04);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.04);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.45, 0, 0.55, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;
}

/* --- Reset & Base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--near-black);
  background-color: var(--white);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

@media (max-width: 768px) {
  h1 { font-size: var(--text-4xl); }
  h2 { font-size: var(--text-3xl); }
  h3 { font-size: var(--text-2xl); }
  h4 { font-size: var(--text-xl); }
}

p {
  line-height: var(--leading-normal);
  max-width: 65ch;
}

/* --- Layout Containers --- */
.container {
  width: 100%;
  max-width: var(--content-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.container--wide {
  max-width: var(--max-width);
}

.container--narrow {
  max-width: 800px;
}

.section {
  padding-block: var(--space-16);
}

.section--sm {
  padding-block: var(--space-10);
}

.section--lg {
  padding-block: var(--space-24);
}

/* --- Header / Navigation --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-base) var(--ease-out);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.nav-primary {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-primary a {
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  color: var(--near-black);
  position: relative;
  padding-block: var(--space-2);
  transition: color var(--duration-fast);
}

.nav-primary a:hover,
.nav-primary a.active {
  color: var(--green-primary);
}

.nav-primary a::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--duration-base) var(--ease-out);
}

.nav-primary a:hover::after,
.nav-primary a.active::after {
  width: 100%;
}

.nav-account {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.nav-account a {
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--near-black);
  transition: color var(--duration-fast);
}

.nav-account a:hover {
  color: var(--green-primary);
}

.find-store-link {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--near-black) !important;
  transition: color var(--duration-fast);
}

.find-store-link:hover {
  color: var(--green-primary) !important;
}

.find-store-link::after {
  display: none !important;
}

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--near-black);
  border-radius: 2px;
  transition: all var(--duration-base) var(--ease-out);
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

@media (max-width: 1024px) {
  .nav-toggle {
    display: flex;
  }

  .nav-primary,
  .nav-account {
    display: none;
  }

  .nav-primary.open,
  .nav-account.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--white);
    padding: var(--space-6);
    border-bottom: 1px solid var(--gray-200);
    box-shadow: var(--shadow-lg);
  }

  .nav-primary.open {
    z-index: 10;
  }

  .nav-account.open {
    top: auto;
    z-index: 9;
  }
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-full);
  transition: all var(--duration-base) var(--ease-out);
  cursor: pointer;
  white-space: nowrap;
}

.btn--primary {
  background: var(--green-primary);
  color: var(--white);
}

.btn--primary:hover {
  background: var(--green-primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn--outline {
  background: transparent;
  color: var(--green-primary);
  border: 2px solid var(--green-primary);
}

.btn--outline:hover {
  background: var(--green-primary);
  color: var(--white);
}

.btn--dark {
  background: var(--dark-forest);
  color: var(--white);
}

.btn--dark:hover {
  background: var(--near-black);
  transform: translateY(-1px);
}

.btn--cream {
  background: var(--warm-cream);
  color: var(--dark-forest);
}

.btn--cream:hover {
  background: var(--warm-cream-light);
  transform: translateY(-1px);
}

.btn--white {
  background: var(--white);
  color: var(--green-primary);
}

.btn--white:hover {
  background: var(--gray-50);
  transform: translateY(-1px);
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
}

.btn--icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
}

/* --- Cards --- */
.card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-base) var(--ease-out);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card__image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: var(--gray-100);
}

.card__body {
  padding: var(--space-6);
}

.card__tag {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--green-primary);
  margin-bottom: var(--space-2);
}

.card__title {
  font-size: var(--text-xl);
  margin-bottom: var(--space-2);
}

.card__text {
  font-size: var(--text-sm);
  color: var(--gray-500);
  margin-bottom: var(--space-4);
}

/* --- Promo Sections --- */
.promo-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 480px;
}

.promo-section--reverse {
  direction: rtl;
}

.promo-section--reverse > * {
  direction: ltr;
}

.promo__content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: var(--space-12);
}

.promo__image {
  position: relative;
  overflow: hidden;
}

.promo__image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-6xl);
}

.promo__subtitle {
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  margin-bottom: var(--space-3);
}

.promo__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
  max-width: 20ch;
}

.promo__text {
  font-size: var(--text-lg);
  color: var(--gray-500);
  margin-bottom: var(--space-6);
  max-width: 45ch;
}

@media (max-width: 768px) {
  .promo-section {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .promo__content {
    padding: var(--space-8);
  }

  .promo__image {
    min-height: 280px;
    order: -1;
  }

  .promo__title {
    font-size: var(--text-3xl);
  }
}

/* --- Breadcrumb --- */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  color: var(--gray-400);
}

.breadcrumb a {
  color: var(--gray-500);
  transition: color var(--duration-fast);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb__sep {
  color: var(--gray-300);
}

/* --- Tabs --- */
.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  border-bottom: 2px solid var(--gray-200);
  padding-bottom: 0;
  margin-bottom: var(--space-8);
}

.tab-btn {
  padding: var(--space-3) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--gray-500);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: all var(--duration-base);
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.tab-btn:hover {
  color: var(--green-primary);
}

.tab-btn.active {
  color: var(--green-primary);
  border-bottom-color: var(--green-primary);
}

.tab-content {
  display: none;
  animation: fadeIn var(--duration-base) var(--ease-out);
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* --- Carousel --- */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-4);
  transition: transform var(--duration-slow) var(--ease-out);
  will-change: transform;
}

.carousel__slide {
  flex: 0 0 auto;
}

.carousel__nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-lg);
  color: var(--near-black);
  transition: all var(--duration-base);
}

.carousel__btn:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.carousel__btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel__btn:disabled:hover {
  background: var(--white);
  border-color: var(--gray-200);
  color: var(--near-black);
}

/* --- Gift Card --- */
.gift-card {
  width: 180px;
  height: 112px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: var(--text-sm);
  text-align: center;
  color: var(--white);
  padding: var(--space-2);
  cursor: pointer;
  transition: all var(--duration-base) var(--ease-out);
  position: relative;
  overflow: hidden;
  flex-shrink: 0;
}

.gift-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.gift-card--spring { background: linear-gradient(135deg, oklch(55% 0.15 152), oklch(70% 0.12 130)); }
.gift-card--perk { background: linear-gradient(135deg, oklch(65% 0.18 75), oklch(80% 0.12 60)); }
.gift-card--friend { background: linear-gradient(135deg, oklch(55% 0.12 200), oklch(70% 0.1 220)); }
.gift-card--thank { background: linear-gradient(135deg, oklch(50% 0.1 30), oklch(65% 0.08 45)); }
.gift-card--star { background: linear-gradient(135deg, oklch(75% 0.16 80), oklch(85% 0.1 75)); color: var(--dark-forest); }
.gift-card--work { background: linear-gradient(135deg, oklch(35% 0.08 55), oklch(50% 0.06 60)); }
.gift-card--birthday { background: linear-gradient(135deg, oklch(65% 0.2 340), oklch(75% 0.15 350)); }
.gift-card--celebrate { background: linear-gradient(135deg, oklch(60% 0.2 280), oklch(70% 0.15 300)); }
.gift-card--yay { background: linear-gradient(135deg, oklch(70% 0.18 55), oklch(80% 0.12 70)); color: var(--dark-forest); }
.gift-card--encourage { background: linear-gradient(135deg, oklch(52% 0.17 152), oklch(68% 0.12 155)); }
.gift-card--greenbean { background: linear-gradient(135deg, var(--dark-forest), var(--green-primary)); }
.gift-card--cafe { background: linear-gradient(135deg, oklch(40% 0.08 55), oklch(55% 0.06 60)); }
.gift-card--heritage { background: linear-gradient(135deg, oklch(30% 0.06 148), oklch(45% 0.08 55)); }

/* --- Toggle / Switch --- */
.toggle-group {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: var(--space-1);
}

.toggle-btn {
  padding: var(--space-2) var(--space-5);
  font-size: var(--text-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  color: var(--gray-500);
  transition: all var(--duration-base);
}

.toggle-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

/* --- Accordion --- */
.accordion {
  border-top: 1px solid var(--gray-200);
}

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--near-black);
  cursor: pointer;
}

.accordion__icon {
  transition: transform var(--duration-base) var(--ease-out);
  font-size: var(--text-lg);
}

.accordion__trigger.open .accordion__icon {
  transform: rotate(180deg);
}

.accordion__panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out);
}

.accordion__panel.open {
  max-height: 500px;
}

.accordion__panel a {
  display: block;
  padding: var(--space-2) 0;
  font-size: var(--text-sm);
  color: var(--gray-500);
  transition: color var(--duration-fast);
}

.accordion__panel a:hover {
  color: var(--green-primary);
}

/* --- Footer --- */
.site-footer {
  background: var(--dark-forest);
  color: var(--gray-300);
  padding-block: var(--space-16);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wide);
  color: var(--white);
  margin-bottom: var(--space-4);
}

.footer-col a {
  display: block;
  font-size: var(--text-sm);
  color: var(--gray-300);
  padding-block: var(--space-1);
  transition: color var(--duration-fast);
}

.footer-col a:hover {
  color: var(--warm-cream);
}

.footer-bottom {
  margin-top: var(--space-12);
  padding-top: var(--space-6);
  border-top: 1px solid oklch(40% 0.02 148);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: var(--text-xs);
  color: var(--gray-400);
}

.footer-social {
  display: flex;
  gap: var(--space-4);
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  border: 1px solid oklch(50% 0.02 148);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  transition: all var(--duration-base);
}

.footer-social a:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-col h4 {
    display: none;
  }

  .footer-col .footer-links-list {
    display: none;
  }

  .footer-col.accordion-mobile .accordion__trigger {
    display: flex;
  }

  .footer-col.accordion-mobile .footer-links-list {
    display: none;
  }

  .footer-col.accordion-mobile .accordion__panel.open .footer-links-list {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }
}

/* Desktop: hide accordion triggers */
@media (min-width: 769px) {
  .footer-col .accordion__trigger {
    display: none;
  }

  .footer-col .accordion__panel {
    max-height: none !important;
    overflow: visible;
  }

  .footer-col .accordion__panel .footer-links-list {
    display: block !important;
  }
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--dark-forest);
  color: var(--gray-200);
  padding: var(--space-6);
  box-shadow: 0 -4px 20px oklch(0% 0 0 / 0.15);
  transform: translateY(0);
  transition: transform var(--duration-slow) var(--ease-out);
}

.cookie-banner.hidden {
  transform: translateY(110%);
}

.cookie-banner__inner {
  max-width: var(--content-width);
  margin-inline: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.cookie-banner__text h3 {
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--white);
  margin-bottom: var(--space-1);
}

.cookie-banner__text p {
  font-size: var(--text-sm);
  max-width: 55ch;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
}

@media (max-width: 768px) {
  .cookie-banner__inner {
    flex-direction: column;
    text-align: center;
  }
}

/* --- Utility --- */
.text-center { text-align: center; }
.text-green { color: var(--green-primary); }
.text-cream { color: var(--warm-cream); }
.text-dark { color: var(--dark-forest); }
.bg-green-light { background: var(--green-primary-light); }
.bg-cream { background: var(--warm-cream-light); }
.bg-off-white { background: var(--off-white); }
.bg-forest { background: var(--dark-forest); }
.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }

/* --- Image Placeholder --- */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  background: var(--gray-100);
  color: var(--gray-300);
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--gray-100);
}

::-webkit-scrollbar-thumb {
  background: var(--gray-300);
  border-radius: var(--radius-full);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--gray-400);
}

raw_arguments.content:
/* ============================================
   GreenBean Coffee — Design System
   Palette: OKLCH perceptual color space
   Typography: DM Serif Display + Inter
   ============================================ */

/* --- Design Tokens --- */
:root {
  /* Primary Brand */
  --green-primary: oklch(52% 0.17 152);
  --green-primary-hover: oklch(45% 0.18 152);
  --green-primary-light: oklch(92% 0.04 152);
  --green-primary-muted: oklch(75% 0.1 152);
  --dark-forest: oklch(30% 0.03 148);
  --warm-cream: oklch(87% 0.07 75);
  --warm-cream-light: oklch(94% 0.04 75);

  /* Neutrals */
  --white: oklch(100% 0 0);
  --off-white: oklch(97% 0.005 100);
  --gray-50: oklch(95% 0.005 100);
  --gray-100: oklch(92% 0.005 100);
  --gray-200: oklch(85% 0.008 100);
  --gray-300: oklch(75% 0.01 100);
  --gray-400: oklch(60% 0.01 100);
  --gray-500: oklch(50% 0.01 100);
  --gray-600: oklch(40% 0.01 100);
  --gray-700: oklch(30% 0.01 100);
  --gray-800: oklch(25% 0.01 100);
  --near-black: oklch(20% 0.02 148);

  /* Accent */
  --coffee-brown: oklch(38% 0.08 55);
  --coffee-brown-light: oklch(55% 0.09 55);
  --gold-accent: oklch(80% 0.14 80);
  --mango-accent: oklch(78% 0.15 75);
  --lavender-accent: oklch(72% 0.1 300);

  /* Semantic */
  --color-success: oklch(60% 0.18 145);
  --color-error: oklch(55% 0.2 25);
  --color-warning: oklch(75% 0.15 80);

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  --leading-tight: 1.15;
  --leading-snug: 1.3;
  --leading-normal: 1.6;
  --leading-relaxed: 1.75;

  --tracking-tight: -0.02em;
  --tracking-normal: 0;
  --tracking-wide: 0.02em;

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --max-width: 1440px;
  --content-width: 1200px;
  --sidebar-width: 280px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.08), 0 2px 4px -2px oklch(0% 0 0 / 0.04);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.04);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.04);

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.45, 0, 0.55, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;
}

/* --- Reset & Base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--near-black);
  background-color: var(--white);
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }

@media (max-width: 768px) {
  h1 { font-size: var(--text-4xl); }
  h2 { font-size: var(--text-3xl); }
  h3 { font-size: var(--text-2xl); }
  h4 { font-size: var(--text-xl); }
}

p {
  line-height: var(--leading-normal);
  max-width: 65ch;
}

/* --- Layout Containers --- */
.container {
  width: 100%;
  max-width: var(--content-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.container--wide {
  max-width: var(--max-width);
}

.container--narrow {
  max-width: 800px;
}

.section {
  padding-block: var(--space-16);
}

.section--sm {
  padding-block: var(--space-10);
}

.section--lg {
  padding-block: var(--space-24);
}

/* --- Header / Navigation --- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--duration-base) var(--ease-out);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: var(--space-6);
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  color: var(--green-primary);
  flex-shrink: 0;
}

.header-logo svg {
  width: 36px;
  height: 36px;
}

.nav-primary {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-primary a {
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
