    // Mobile nav
    const navToggle = document.getElementById('navToggle');
    const navPrimary = document.getElementById('navPrimary');
    const navAccount = document.getElementById('navAccount');
    if (navToggle) {
      navToggle.addEventListener('click', () => {
        navToggle.classList.toggle('active');
        navPrimary.classList.toggle('open');
        navAccount.classList.toggle('open');
      });
    }
    window.addEventListener('scroll', () => {
      document.getElementById('siteHeader').classList.toggle('scrolled', window.scrollY > 10);
    });

    // Featured Carousel
    (function() {
      const track = document.getElementById('featuredTrack');
      const prevBtn = document.getElementById('featuredPrev');
      const nextBtn = document.getElementById('featuredNext');
      let position = 0;
      const cardWidth = 230; // 200 + 30 gap
      const visibleCards = () => Math.floor(document.getElementById('featuredCarousel').offsetWidth / cardWidth);
      const maxPosition = () => Math.max(0, track.children.length - visibleCards());

      function updateCarousel() {
        track.style.transform = `translateX(-${position * cardWidth}px)`;
        prevBtn.disabled = position <= 0;
        nextBtn.disabled = position >= maxPosition();
      }

      prevBtn.addEventListener('click', () => {
        position = Math.max(0, position - 1);
        updateCarousel();
      });

      nextBtn.addEventListener('click', () => {
        position = Math.min(maxPosition(), position + 1);
        updateCarousel();
      });

      updateCarousel();
      window.addEventListener('resize', updateCarousel);
    })();

    // Category Carousels
    document.querySelectorAll('.category-section').forEach(section => {
      const track = section.querySelector('.category-carousel__track');
      const prevBtn = section.querySelector('.cat-prev');
      const nextBtn = section.querySelector('.cat-next');
      let position = 0;
      const cardWidth = 210;

      function visibleCards() {
        return Math.floor(section.querySelector('.category-carousel').offsetWidth / cardWidth);
      }

      function maxPosition() {
        return Math.max(0, track.children.length - visibleCards());
      }

      function updateCarousel() {
        track.style.transform = `translateX(-${position * cardWidth}px)`;
        prevBtn.disabled = position <= 0;
        nextBtn.disabled = position >= maxPosition();
      }

      prevBtn.addEventListener('click', () => {
        position = Math.max(0, position - 1);
        updateCarousel();
      });

      nextBtn.addEventListener('click', () => {
        position = Math.min(maxPosition(), position + 1);
        updateCarousel();
      });

      updateCarousel();
      window.addEventListener('resize', updateCarousel);
    });

    // FAQ Accordion
    document.querySelectorAll('.faq-question').forEach(question => {
      question.addEventListener('click', () => {
        const answer = question.nextElementSibling;
        const isOpen = question.classList.contains('open');

        // Close all
        document.querySelectorAll('.faq-question').forEach(q => q.classList.remove('open'));
        document.querySelectorAll('.faq-answer').forEach(a => a.classList.remove('open'));

        if (!isOpen) {
          question.classList.add('open');
          answer.classList.add('open');
        }
      });
    });

    // Footer accordion
    document.querySelectorAll('.footer-col.accordion-mobile .accordion__trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const panel = trigger.nextElementSibling;
        const isOpen = trigger.classList.contains('open');
        document.querySelectorAll('.footer-col.accordion-mobile .accordion__trigger').forEach(t => {
          t.classList.remove('open');
          t.setAttribute('aria-expanded', 'false');
          t.nextElementSibling.classList.remove('open');
        });
        if (!isOpen) {
          trigger.classList.add('open');
          trigger.setAttribute('aria-expanded', 'true');
          panel.classList.add('open');
        }
      });
    });
  </script>
