  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Find a Store — GreenBean Coffee</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="styles.css">
  <style>
    .locator-layout {
      display: grid;
      grid-template-columns: 420px 1fr;
      min-height: calc(100vh - 72px);
      max-width: var(--max-width);
      margin-inline: auto;
    }

    /* Search Panel */
    .search-panel {
      padding: var(--space-6);
      border-right: 1px solid var(--gray-200);
      overflow-y: auto;
      background: var(--white);
    }

    .search-panel__header {
      margin-bottom: var(--space-6);
    }

    .search-panel__header h1 {
      font-size: var(--text-2xl);
      margin-bottom: var(--space-4);
    }

    /* Order type toggle */
    .order-type-toggle {
      margin-bottom: var(--space-5);
    }

    /* Search input */
    .search-input-wrapper {
      position: relative;
      margin-bottom: var(--space-4);
    }

    .search-input-wrapper svg {
      position: absolute;
      left: var(--space-4);
      top: 50%;
      transform: translateY(-50%);
      color: var(--gray-400);
    }

    .search-input {
      width: 100%;
      padding: var(--space-3) var(--space-4) var(--space-3) var(--space-10);
      font-family: var(--font-body);
      font-size: var(--text-base);
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      outline: none;
      transition: border-color var(--duration-fast);
      background: var(--off-white);
    }

    .search-input:focus {
      border-color: var(--green-primary);
      background: var(--white);
    }

    .search-input::placeholder {
      color: var(--gray-400);
    }

    /* Search suggestions */
    .search-suggestions {
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      z-index: 10;
      display: none;
      margin-top: var(--space-1);
    }

    .search-suggestions.visible {
      display: block;
    }

    .search-suggestion {
      padding: var(--space-3) var(--space-4);
      font-size: var(--text-sm);
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: var(--space-3);
      transition: background var(--duration-fast);
    }

    .search-suggestion:hover {
      background: var(--green-primary-light);
    }

    .search-suggestion:first-child {
      border-radius: var(--radius-lg) var(--radius-lg) 0 0;
    }

    .search-suggestion:last-child {
      border-radius: 0 0 var(--radius-lg) var(--radius-lg);
    }

    /* Filter button & panel */
    .filter-bar {
      display: flex;
      gap: var(--space-3);
      margin-bottom: var(--space-5);
    }

    .filter-btn {
      display: flex;
      align-items: center;
      gap: var(--space-2);
      padding: var(--space-2) var(--space-4);
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: var(--text-sm);
      font-weight: 600;
      color: var(--gray-600);
      background: var(--white);
      cursor: pointer;
      transition: all var(--duration-fast);
    }

    .filter-btn:hover {
      border-color: var(--green-primary);
      color: var(--green-primary);
    }

    .filter-btn.active {
      border-color: var(--green-primary);
      background: var(--green-primary-light);
      color: var(--green-primary);
    }

    .filter-panel {
      display: none;
      background: var(--off-white);
      border-radius: var(--radius-lg);
      padding: var(--space-5);
      margin-bottom: var(--space-5);
    }

    .filter-panel.open {
      display: block;
      animation: fadeIn var(--duration-base) var(--ease-out);
    }

    .filter-panel h4 {
      font-family: var(--font-body);
      font-size: var(--text-sm);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: var(--tracking-wide);
      margin-bottom: var(--space-4);
      color: var(--gray-600);
    }

    .filter-options {
      display: flex;
      flex-wrap: wrap;
      gap: var(--space-2);
    }

    .filter-chip {
      padding: var(--space-2) var(--space-4);
      border: 1px solid var(--gray-300);
      border-radius: var(--radius-full);
      font-size: var(--text-xs);
      font-weight: 500;
      cursor: pointer;
      transition: all var(--duration-fast);
      background: var(--white);
    }

    .filter-chip:hover,
    .filter-chip.selected {
      background: var(--green-primary);
      border-color: var(--green-primary);
      color: var(--white);
    }

    /* Store Results */
    .results-header {
      font-size: var(--text-sm);
      color: var(--gray-500);
      margin-bottom: var(--space-4);
    }

    .store-list {
      display: flex;
      flex-direction: column;
      gap: var(--space-3);
    }

    .store-card {
      padding: var(--space-4);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      cursor: pointer;
      transition: all var(--duration-fast);
    }

    .store-card:hover {
      border-color: var(--green-primary);
      background: var(--green-primary-light);
    }

    .store-card__name {
      font-size: var(--text-base);
      font-weight: 600;
      margin-bottom: var(--space-1);
    }

    .store-card__address {
      font-size: var(--text-sm);
      color: var(--gray-500);
      margin-bottom: var(--space-2);
    }

    .store-card__meta {
      display: flex;
      align-items: center;
      gap: var(--space-4);
      font-size: var(--text-xs);
    }

    .store-card__hours {
      color: var(--green-primary);
      font-weight: 600;
    }

    .store-card__features {
      display: flex;
      gap: var(--space-2);
      flex-wrap: wrap;
    }

    .store-feature {
      display: inline-flex;
      align-items: center;
      gap: var(--space-1);
      padding: var(--space-1) var(--space-2);
      background: var(--gray-50);
      border-radius: var(--radius-sm);
      font-size: var(--text-xs);
      color: var(--gray-600);
    }

    .store-card__actions {
      margin-top: var(--space-3);
      display: flex;
      gap: var(--space-2);
    }

    /* Map View */
    .map-view {
      position: relative;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 500px;
    }

    .map-placeholder {
      width: 100%;
      height: 100%;
      min-height: calc(100vh - 72px);
      background:
        linear-gradient(135deg, oklch(93% 0.02 152) 25%, oklch(96% 0.01 100) 25%, oklch(96% 0.01 100) 50%, oklch(93% 0.02 152) 50%, oklch(93% 0.02 152) 75%, oklch(96% 0.01 100) 75%);
      background-size: 40px 40px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }

    .map-pins {
      position: absolute;
      inset: 0;
    }

    .map-pin {
      position: absolute;
      width: 36px;
      height: 36px;
      border-radius: var(--radius-full) var(--radius-full) var(--radius-full) 4px;
      background: var(--green-primary);
      color: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: var(--text-lg);
      box-shadow: var(--shadow-md);
      cursor: pointer;
      transform: rotate(-45deg);
      transition: transform var(--duration-base);
    }

    .map-pin:hover {
      transform: rotate(-45deg) scale(1.2);
    }

    .map-pin span {
      transform: rotate(45deg);
      font-size: var(--text-sm);
    }

    .map-overlay {
      position: absolute;
      bottom: var(--space-6);
      left: var(--space-6);
      background: var(--white);
      padding: var(--space-4) var(--space-5);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      font-size: var(--text-sm);
      color: var(--gray-500);
    }

    .map-logo {
      position: absolute;
      top: var(--space-4);
      right: var(--space-4);
      background: var(--white);
      padding: var(--space-2) var(--space-3);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-md);
      font-size: var(--text-xs);
      color: var(--gray-400);
    }

    @media (max-width: 1024px) {
      .locator-layout {
        grid-template-columns: 1fr;
      }

      .map-view {
        min-height: 300px;
        order: -1;
      }

      .map-placeholder {
        min-height: 300px;
      }
    }

    @media (max-width: 768px) {
      .search-panel {
        padding: var(--space-4);
      }
    }
  </style>
