  <script>
    // Mobile nav
    const navToggle = document.getElementById('navToggle');
    const navPrimary = document.getElementById('navPrimary');
    const navAccount = document.getElementById('navAccount');
    if (navToggle) {
      navToggle.addEventListener('click', () => {
        navToggle.classList.toggle('active');
        navPrimary.classList.toggle('open');
        navAccount.classList.toggle('open');
      });
    }
    window.addEventListener('scroll', () => {
      document.getElementById('siteHeader').classList.toggle('scrolled', window.scrollY > 10);
    });

    // Search suggestions
    const storeSearch = document.getElementById('storeSearch');
    const searchSuggestions = document.getElementById('searchSuggestions');
    const suggestionItems = searchSuggestions.querySelectorAll('.search-suggestion');

    storeSearch.addEventListener('input', () => {
      const val = storeSearch.value.toLowerCase().trim();
      if (val.length > 0) {
        let hasVisible = false;
        suggestionItems.forEach(item => {
          const text = item.getAttribute('data-value').toLowerCase();
          if (text.includes(val)) {
            item.style.display = 'flex';
            hasVisible = true;
          } else {
            item.style.display = 'none';
          }
        });
        searchSuggestions.classList.toggle('visible', hasVisible);
      } else {
        searchSuggestions.classList.remove('visible');
      }
    });

    storeSearch.addEventListener('focus', () => {
      if (storeSearch.value.trim().length > 0) {
        searchSuggestions.classList.add('visible');
      }
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.search-input-wrapper')) {
        searchSuggestions.classList.remove('visible');
      }
    });

    suggestionItems.forEach(item => {
      item.addEventListener('click', () => {
        storeSearch.value = item.getAttribute('data-value');
        searchSuggestions.classList.remove('visible');
      });
    });

    // Filter toggle
    const filterToggle = document.getElementById('filterToggle');
    const filterPanel = document.getElementById('filterPanel');

    filterToggle.addEventListener('click', () => {
      filterPanel.classList.toggle('open');
      filterToggle.classList.toggle('active');
    });

    // Filter chips
    document.querySelectorAll('.filter-chip').forEach(chip => {
      chip.addEventListener('click', () => {
        chip.classList.toggle('selected');
      });
    });

    // Order type toggle
    const toggleBtns = document.querySelectorAll('.toggle-btn');
    const storeCards = document.querySelectorAll('.store-card');
    const resultsHeader = document.getElementById('resultsHeader');

    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        toggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const type = btn.getAttribute('data-type');
        let visibleCount = 0;

        storeCards.forEach(card => {
          const types = card.getAttribute('data-type');
          if (types.includes(type)) {
            card.style.display = 'block';
            visibleCount++;
          } else {
            card.style.display = 'none';
          }
        });

        resultsHeader.textContent = `${visibleCount} store${visibleCount !== 1 ? 's' : ''} for ${type}`;
      });
    });
  </script>
